package com.smartcanteen.model;

/**
 * Base entity representing a generic system user (Student or Admin).
 * Demonstrates Encapsulation and acts as the Superclass for Inheritance.
 */
public class User {

    private int userId;
    private String name;
    private String email;
    private String password;
    private String role; // "STUDENT", "ADMIN"

    /**
     * Default constructor.
     */
    public User() {
    }

    /**
     * Constructor for creating a new user before ID is generated by the database.
     */
    public User(String name, String email, String password, String role) {
        this.name = name;
        this.email = email;
        this.password = password;
        this.role = role;
    }

    /**
     * Full constructor for retrieving an existing user from the database.
     */
    public User(int userId, String name, String email, String password, String role) {
        this.userId = userId;
        this.name = name;
        this.email = email;
        this.password = password;
        this.role = role;
    }

    // Getters and Setters (Encapsulation)

    public int getUserId() {
        return userId;
    }

    public void setUserId(int userId) {
        this.userId = userId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public String getPassword() {
        return password;
    }

    public void setPassword(String password) {
        this.password = password;
    }

    public String getRole() {
        return role;
    }

    public void setRole(String role) {
        this.role = role;
    }

    @Override
    public String toString() {
        return "User{" +
                "userId=" + userId +
                ", name='" + name + '\'' +
                ", email='" + email + '\'' +
                ", role='" + role + '\'' +
                '}';
    }
}
